head.script:
scwin.onpageload = function() {
    ipt_test1.setValue(99991212);
};
scwin.onpageunload = function() {};

scwin.checkVal1 = function() {
	return WebSquare.wUnit.getDomById('ipt_test1_calendar_selectbox_year_label').innerText == '2030년';
}
scwin.checkVal2 = function() {
	return WebSquare.wUnit.getDomById('ipt_test1_calendar_selectbox_month_label').innerText == '1월';
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('ipt_test1_img').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('ipt_test1_calendar_last_year').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('ipt_test1_calendar_last_year').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('ipt_test1_calendar_last_year').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_header_next_month')[0].click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_header_next_year')[0].click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
